assert len(DATA) == 10
TARGETS = ["A", "B", "A", "A", "A", "B", "A", "A", "A", "A"]
for i, (prompt, options, answer, explanation, strategy, steps) in enumerate(DATA, 1):
    target = TARGETS[i - 1]
    if target != "A":
        ti = ord(target) - ord("A")
        options = options[1:ti + 1] + [options[0]] + options[ti + 1:]
        explanation = explanation.replace("A ", f"{target} ")
        strategy = strategy.replace("A ", f"{target} ")
        steps = [s.replace("A ", f"{target} ") for s in steps]
        answer = target
    item = {"id": f"question-chinese-content-bc-iv-2-{i}", "subject": "chinese", "type": "single-choice", "prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(options)], "knowledgeIds": ["kg-chinese-content-bc-iv-2"], "difficulty": "medium", "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校公開國文段考與課程資料；只研究描述、列舉、因果、問題解決、比較、分類與定義。", "authoringNote": "依官方語文領域課綱、單元 KG 與三個公立學校公開來源，獨立改寫說明文組織題；未複製原文、選項、篇章、圖片或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-13", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}
